WITH reason_agg AS ( SELECT cp.cp_catalog_page_id AS cp_id, cp.cp_department, r.r_reason_desc, cd.cd_gender, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_fee) AS total_fee FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_quantity >= 10 GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_desc, cd.cd_gender ), fee_ratio AS ( SELECT cp_id, cp_department, r_reason_desc, cd_gender, total_return_amount, total_fee, (total_fee / NULLIF(total_return_amount,0)) AS fee_to_return_ratio FROM reason_agg ) SELECT cp_id, cp_department, r_reason_desc, cd_gender, total_return_amount, total_fee, fee_to_return_ratio, CASE WHEN fee_to_return_ratio > 0.2 THEN 'High Fee Ratio' ELSE 'Normal Fee Ratio' END AS fee_category FROM fee_ratio WHERE total_return_amount > 5000 ORDER BY fee_to_return_ratio DESC, cp_id
